-- Utility CMM-aligned Canonical Data Model (Silver) v1.0.0 | source: Databricks lakehouse-industry-data-models energy_utilities v1 ECM | generated 2026-10-13
-- 00 | Catalog and schemas (subject areas). Run first.

CREATE CATALOG IF NOT EXISTS `utility_cmm_silver` COMMENT 'Utility CMM-aligned canonical data model - silver layer (IEC CIM 61970/61968/62325 aligned).';
USE CATALOG `utility_cmm_silver`;

CREATE SCHEMA IF NOT EXISTS `asset` COMMENT 'Utility asset lifecycle management including generation units, transmission towers, distribution poles, transformers, switchgear, protection relays, substation equipment, fleet vehicles, and facilities. Manages asset registry, condition assessments, work orders, preventive/corrective maintenance schedules, depreciation schedules, capital projects, spare parts inventory, and O&M cost tracking via Ventyx Asset Suite EAM. Supports CAPEX/OPEX planning and RAB valuation.';
ALTER SCHEMA `asset` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'asset', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61968::Assets; IEC61968::Work; IEC61968::InfERPSupport', 'cmm_standards' = 'IEC 61968-4; IEC 61968-6; ISO 55000/55001; ISO 14224');
CREATE SCHEMA IF NOT EXISTS `billing` COMMENT 'SSOT for all revenue cycle data — rate schedules, tariff structures, invoice generation, payment processing, collections, dunning, payment arrangements, deposit management, and revenue recognition. Manages TOU, CPP, and tiered rate calculations, budget billing plans, and financial adjustments within SAP IS-U FICA and Oracle CC&B. Owns accounts receivable ledger entries, write-offs, and dispute resolution supporting SOX financial controls.';
ALTER SCHEMA `billing` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'billing', 'cmm_division' = 'business', 'cmm_cim_packages' = 'IEC61968::Customers; IEC61968::PaymentMetering; IEC61968::InfCustomers', 'cmm_standards' = 'IEC 61968-8; IEC 61968-10; FERC USoA; ASC 606; NAESB REQ.21 ESPI');
CREATE SCHEMA IF NOT EXISTS `compliance` COMMENT 'Regulatory compliance management including NERC CIP audits, FERC reporting, PUC rate cases, environmental permits, emissions reporting to EPA, reliability standards documentation, SOX controls, and CPCN applications. Manages compliance obligations, audit trails, regulatory filings, evidence collection, enforcement action records, and regulatory correspondence. Serves as SSOT for compliance posture reporting to the Board and external regulators.';
ALTER SCHEMA `compliance` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'compliance', 'cmm_division' = 'corporate', 'cmm_cim_packages' = 'IEC61968::Common (Document/ActivityRecord extensions)', 'cmm_standards' = 'NERC Reliability Standards (CIP, PRC, TOP, BAL, EOP); FERC; EPA 40 CFR Part 75; SOX 404');
CREATE SCHEMA IF NOT EXISTS `customer` COMMENT 'SSOT for all customer identity, account, and relationship data across residential, commercial, and industrial segments. Manages customer profiles, service agreements, premises, contact information, premise-to-account linkages, credit classifications, and multi-channel engagement history within CIS platforms (SAP IS-U, Oracle CC&B). Supports NEM participants, BTM customers, and DER-enrolled accounts. Central reference for all downstream billing, metering, and demand response domains.';
ALTER SCHEMA `customer` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'customer', 'cmm_division' = 'business', 'cmm_cim_packages' = 'IEC61968::Customers; IEC61968::Common', 'cmm_standards' = 'IEC 61968-8; NAESB REQ.21 ESPI (Green Button); MultiSpeak CB');
CREATE SCHEMA IF NOT EXISTS `demand` COMMENT 'Demand response programs, load curtailment events, CPP and TOU rate programs, direct load control, behavioral demand response, aggregator management, and customer incentive payments. Manages DR event dispatch, baseline calculations, measurement and verification, interruptible tariff agreements, VPP dispatch records, and integration with wholesale market DR products. Serves as SSOT for enrolled load capacity and program performance reporting to ISO/RTO and PUC.';
ALTER SCHEMA `demand` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'demand', 'cmm_division' = 'business', 'cmm_cim_packages' = 'IEC61968::Metering (DemandResponseProgram, EndDeviceControl); IEC61968-5 DER', 'cmm_standards' = 'IEC 61968-9; IEC 61968-5; OpenADR 2.0b; IEEE 2030.5; FERC Order 2222; NAESB WEQ-015');
CREATE SCHEMA IF NOT EXISTS `distribution` COMMENT 'Medium- and low-voltage distribution network operations including feeders, poles, transformers, service drops, sectionalizing devices, FLISR automation, volt-VAR optimization, and last-mile delivery to customer premises. Manages distribution grid topology, load balancing, DMS/ADMS integration via GE PowerOn ADMS and Esri ArcGIS Utility Network. Tracks SAIDI, SAIFI, and CAIDI reliability indices for PUC reporting.';
ALTER SCHEMA `distribution` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'distribution', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61970::Core; IEC61970::Wires; IEC61968::Operations', 'cmm_standards' = 'IEC 61968-13 CDPSM; IEC 61968-3; IEEE 1366; Esri ArcGIS Utility Network; MultiSpeak');
CREATE SCHEMA IF NOT EXISTS `finance` COMMENT 'Corporate financial management including general ledger, accounts payable and receivable, capital budgeting, CAPEX and OPEX tracking, regulatory asset base (RAB) valuations, WACC calculations, EBITDA reporting, rate case financial models, ROE filings, depreciation, FERC account codes, cost allocation, and SOX-compliant financial controls within SAP S/4HANA FI/CO. Distinct from billing (customer revenue) — owns enterprise-level financial consolidation and treasury.';
ALTER SCHEMA `finance` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'finance', 'cmm_division' = 'corporate', 'cmm_cim_packages' = 'IEC61968::InfERPSupport; IEC61968::InfWork', 'cmm_standards' = 'IEC 61968-10; FERC USoA (18 CFR Part 101); US GAAP (ASC 980, 740); SOX 404');
CREATE SCHEMA IF NOT EXISTS `forecast` COMMENT 'Load forecasting, generation forecasting, renewable intermittency prediction, peak demand planning, weather correlation analysis, and long-term capacity planning. Manages short-term operational forecasts, seasonal planning, and IRP scenario modeling for resource adequacy and grid reliability. Supports operational decision-making for dispatch, procurement, and infrastructure investment.';
ALTER SCHEMA `forecast` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'forecast', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61970::LoadModel; IEC61970::Core (schedules); IEC61968::Environmental', 'cmm_standards' = 'IEC 61968-5 (DERGroupForecast); NERC MOD-031; ISO 8601');
CREATE SCHEMA IF NOT EXISTS `generation` COMMENT 'Power generation from conventional and renewable sources including CCGT, coal, nuclear, hydro, wind, solar, and biomass facilities. Manages plant operations, unit commitment, dispatch schedules, heat rate optimization, fuel inventory, emissions monitoring, and generation capacity planning. Core SCADA/DCS integration point for real-time generation telemetry via ABB Ability Symphony Plus. Supports IRP, LCOE analysis, and CAPEX planning for generation fleet.';
ALTER SCHEMA `generation` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'generation', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61970::Generation::Production; IEC61970::Core', 'cmm_standards' = 'NERC GADS; EPA CEMS (40 CFR Part 75); EIA-860/923; IEC 62325-301');
CREATE SCHEMA IF NOT EXISTS `grid` COMMENT 'Real-time grid operations including EMS, SCADA telemetry, state estimation, contingency analysis, automatic generation control, load forecasting, system balancing, frequency regulation, and voltage control. Manages grid stability, coordination with balancing authorities, switching orders, and OSIsoft PI historian data integration for operational analytics and post-event review. Supports NERC BAL and TOP reliability standards.';
ALTER SCHEMA `grid` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'grid', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61970::Meas; IEC61970::SCADA; IEC61970::ControlArea; IEC61970::Contingency; IEC61970::StateVariables; IEC61970::OperationalLimits; IEC61970::Topology', 'cmm_standards' = 'IEC 61970-452/456 (CGMES); IEC 60870-6 ICCP; IEEE C37.118; NERC BAL/TOP/IRO');
CREATE SCHEMA IF NOT EXISTS `interconnection` COMMENT 'Customer and third-party interconnection requests for distributed generation, solar installations, battery storage, EV chargers, and other BTM resources. Manages interconnection applications, technical reviews, impact studies, POI specifications, NEM agreements, queue management, and SGIP compliance for DER integration. Distinct from renewable (resource management) — focuses on the application and approval process for grid connection.';
ALTER SCHEMA `interconnection` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'interconnection', 'cmm_division' = 'business', 'cmm_cim_packages' = 'IEC61970::Wires (PowerElectronicsConnection); IEC61968::InfWork', 'cmm_standards' = 'IEEE 1547-2018; UL 1741 SB; FERC Order 2023; FERC Order 2222; IEC 61968-5');
CREATE SCHEMA IF NOT EXISTS `metering` COMMENT 'Advanced metering infrastructure including smart meters, interval data collection, AMI head-end systems, meter reading schedules, VEE (Validation, Estimation, and Editing) processes, TOU and CPP rate programs, and meter asset lifecycle. Manages meter-to-cash data flow, MDM integration via Oracle Utilities MDM, and raw/validated interval data streams feeding billing, demand response, and grid operations domains.';
ALTER SCHEMA `metering` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'metering', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61968::Metering; IEC61968::PaymentMetering', 'cmm_standards' = 'IEC 61968-9; ANSI C12.19/C12.22; IEC 62056 DLMS/COSEM; NAESB REQ.21 ESPI');
CREATE SCHEMA IF NOT EXISTS `outage` COMMENT 'Outage management including unplanned interruptions, planned maintenance windows, storm response, crew dispatch, restoration prioritization, customer notifications, SAIDI/SAIFI/CAIDI tracking, and OMS integration. Manages outage events, switching orders, service restoration workflows, and reliability performance reporting. Distinct from grid domain (real-time control) — focuses on event lifecycle and restoration coordination.';
ALTER SCHEMA `outage` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'outage', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61968::Operations; IEC61968::Customers', 'cmm_standards' = 'IEC 61968-3; IEEE 1366; MultiSpeak OD/OA; EEI Mutual Assistance');
CREATE SCHEMA IF NOT EXISTS `renewable` COMMENT 'Renewable energy resource management including utility-scale wind farms, solar arrays, battery storage, and hydroelectric facilities. Manages DER registration, DERMS integration, REC issuance and retirement, RPS compliance portfolios, renewable generation forecasting, curtailment management, BTM generation tracking, NEM credits, and VPP aggregation configurations. Supports state renewable portfolio standards and clean energy mandates.';
ALTER SCHEMA `renewable` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'renewable', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61970::Wires (PowerElectronics); IEC61968-5 DER; IEC62325::MarketResults', 'cmm_standards' = 'IEC 61968-5; IEEE 1547; IEEE 2030.5; WREGIS/M-RETS/PJM-GATS');
CREATE SCHEMA IF NOT EXISTS `supply` COMMENT 'Utility supply chain including materials management, procurement of transformers, conductors, meters, poles, generation spare parts, fuel supply contracts (gas, coal, uranium), vendor management, inventory warehouses, and logistics. Manages purchase orders, supplier contracts, spare parts catalog, warehouse stock levels, and emergency restoration supply chain within SAP S/4HANA MM. Supports T&D construction material sourcing and supply chain resilience.';
ALTER SCHEMA `supply` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'supply', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61968::InfERPSupport; IEC61968::Assets', 'cmm_standards' = 'IEC 61968-10; UNSPSC; ISO 8000 (master data)');
CREATE SCHEMA IF NOT EXISTS `trading` COMMENT 'Wholesale energy trading, power purchase agreements, bilateral contracts, day-ahead and real-time market participation, LMP pricing, scheduling coordinators, ancillary services procurement, and ETRM position management via OpenLink Endur. Manages market settlements, congestion revenue rights, FTR holdings, counterparty credit exposure, REC tracking, and ISO/RTO interface for energy transactions. Supports FERC market reporting and NAESB scheduling.';
ALTER SCHEMA `trading` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'trading', 'cmm_division' = 'business', 'cmm_cim_packages' = 'IEC62325::MarketCommon; IEC62325::ParticipantInterfaces; IEC62325::MarketResults; IEC62325::ReferenceData; IEC62325::CongestionRevenueRights', 'cmm_standards' = 'IEC 62325-301; IEC 62325-351; NAESB WEQ; FERC EQR; EEI/ISDA Master Agreements');
CREATE SCHEMA IF NOT EXISTS `transmission` COMMENT 'High-voltage bulk power transmission network operations including substations, transmission lines, transformers, circuit breakers, ATC calculations, congestion management, OATT compliance, and interconnection with RTOs/ISOs. Manages transmission rights, FTR positions, power flow models, NERC reliability coordination, and FERC transmission reporting. Integrates with EMS and SCADA for real-time grid state.';
ALTER SCHEMA `transmission` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'transmission', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61970::Core; IEC61970::Wires; IEC61970::Protection; IEC62325::ReferenceData', 'cmm_standards' = 'IEC 61970-452/456 (CGMES); NERC FAC/MOD/TPL/PRC; FERC OATT (Orders 888/890)');
CREATE SCHEMA IF NOT EXISTS `workforce` COMMENT 'Utility workforce management including field crews, linemen, plant operators, engineers, dispatchers, meter readers, and administrative staff. Manages employee records, certifications (NERC CIP personnel risk assessments), OSHA safety compliance, union agreements, crew scheduling, time and attendance, contractor workforce, and labor cost allocations to work orders. Serves as SSOT for personnel identity referenced by asset maintenance, grid operations, and compliance domains.';
ALTER SCHEMA `workforce` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'workforce', 'cmm_division' = 'corporate', 'cmm_cim_packages' = 'IEC61968::Common (Crew, Person); IEC61968::InfERPSupport (ErpPersonnel); IEC61968::InfWork', 'cmm_standards' = 'IEC 61968-6; IEC 61968-10; OSHA 29 CFR 1910.269; NERC CIP-004; DOT 49 CFR Part 40');
CREATE SCHEMA IF NOT EXISTS `gis` COMMENT 'CMM GIS / spatial subject area: CIM Location, PositionPoint and CoordinateSystem, CIM network topology (ConnectivityNode, Terminal), geographical regions and the Esri ArcGIS Utility Network feature/association model. Single source of geometry for every locatable canonical entity.';
ALTER SCHEMA `gis` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'gis', 'cmm_division' = 'operations', 'cmm_cim_packages' = 'IEC61968::Common (Location, PositionPoint, CoordinateSystem); IEC61970::Topology; IEC61970::Core', 'cmm_standards' = 'OGC GeoSPARQL 1.1; ISO 19125 Simple Features; ISO 19111/EPSG; Esri ArcGIS Utility Network; H3');
CREATE SCHEMA IF NOT EXISTS `cmm_meta` COMMENT 'CMM model metadata registry (ISO/IEC 11179 style): CIM class registry, canonical entity/attribute registries, relationships, enumerations, source lineage and data-quality results.';
ALTER SCHEMA `cmm_meta` SET TAGS ('cmm_layer' = 'silver', 'cmm_subject_area' = 'cmm_meta', 'cmm_division' = 'corporate', 'cmm_cim_packages' = '', 'cmm_standards' = 'ISO/IEC 11179 (metadata registry)');
CREATE SCHEMA IF NOT EXISTS `cmm_metrics` COMMENT 'Unity Catalog metric views (KPIs) ported from the ECM source onto the canonical silver model.';
